create type public.app_role as enum ('admin','ustadz','badal','pengawas','wali');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, nama text not null default '', no_hp text not null default '', ukuran_huruf_quran text not null default 'sedang' check(ukuran_huruf_quran in ('kecil','sedang','besar')), persetujuan_data_pada timestamptz);
grant select,insert,update,delete on public.profiles to authenticated; grant all on public.profiles to service_role; alter table public.profiles enable row level security;
create table public.user_roles(user_id uuid references auth.users(id) on delete cascade, role public.app_role not null, primary key(user_id,role));
grant select,insert,update,delete on public.user_roles to authenticated; grant all on public.user_roles to service_role; alter table public.user_roles enable row level security;
create function public.has_role(_user_id uuid,_role public.app_role) returns boolean language sql stable security definer set search_path=public as $$ select _user_id=auth.uid() and exists(select 1 from public.user_roles where user_id=_user_id and role=_role) $$;
revoke all on function public.has_role(uuid,public.app_role) from public,anon; grant execute on function public.has_role(uuid,public.app_role) to authenticated;
create policy roles_read on public.user_roles for select to authenticated using(user_id=auth.uid() or public.has_role(auth.uid(),'admin'));
create policy roles_admin on public.user_roles for all to authenticated using(public.has_role(auth.uid(),'admin')) with check(public.has_role(auth.uid(),'admin'));
create policy profile_read on public.profiles for select to authenticated using(id=auth.uid() or public.has_role(auth.uid(),'admin'));
create policy profile_update on public.profiles for update to authenticated using(id=auth.uid() or public.has_role(auth.uid(),'admin')) with check(id=auth.uid() or public.has_role(auth.uid(),'admin'));
create function public.create_profile() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,nama) values(new.id,coalesce(new.raw_user_meta_data->>'nama','')); return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.create_profile();
create table public.pengaturan_sekolah(id integer primary key default 1 check(id=1),nama_sekolah text not null default 'Sekolah Tahfidz Hidayah Qur''an',logo_url text,alamat text not null default 'Jl. Jahari No.36A, RT.4/RW.7, Sukabumi Sel., Kec. Kb. Jeruk, Kota Jakarta Barat, Daerah Khusus Ibukota Jakarta 11560',kepala_sekolah text not null default '',hari_sekolah text[] not null default array['Senin','Selasa','Rabu','Kamis','Jumat'],satuan_default text not null default 'baris' check(satuan_default in ('baris','halaman')),putaran_manzil_hari integer not null default 15 check(putaran_manzil_hari>0),putaran_sabqi_hari integer not null default 5 check(putaran_sabqi_hari>0));
grant select,insert,update,delete on public.pengaturan_sekolah to authenticated; grant all on public.pengaturan_sekolah to service_role; alter table public.pengaturan_sekolah enable row level security;
create table public.periode(id uuid primary key default gen_random_uuid(),nama text not null,tanggal_mulai date not null,tanggal_selesai date not null,semester integer not null check(semester in(1,2)),tahun_ajaran text not null,check(tanggal_selesai>=tanggal_mulai));
grant select,insert,update,delete on public.periode to authenticated; grant all on public.periode to service_role; alter table public.periode enable row level security;
create table public.halaqah(id uuid primary key default gen_random_uuid(),nama text not null,ustadz_id uuid references public.profiles(id),pengawas_id uuid references public.profiles(id),tahun_ajaran text not null);
grant select,insert,update,delete on public.halaqah to authenticated; grant all on public.halaqah to service_role; alter table public.halaqah enable row level security;
create table public.penugasan_badal(id uuid primary key default gen_random_uuid(),halaqah_id uuid not null references public.halaqah(id) on delete cascade,ustadz_id uuid not null references public.profiles(id),mulai date not null,selesai date not null,check(selesai>=mulai));
grant select,insert,update,delete on public.penugasan_badal to authenticated; grant all on public.penugasan_badal to service_role; alter table public.penugasan_badal enable row level security;
create table public.quran_surah(id integer primary key check(id between 1 and 114),nama_latin text not null,nama_arab text not null,jumlah_ayat integer not null check(jumlah_ayat>0));
grant select,insert,update,delete on public.quran_surah to authenticated; grant all on public.quran_surah to service_role; alter table public.quran_surah enable row level security;
create table public.quran_ayat(id integer primary key check(id between 1 and 6236),surah integer not null references public.quran_surah(id),ayat integer not null check(ayat>0),juz integer not null check(juz between 1 and 30),halaman integer not null check(halaman between 1 and 604),baris_awal integer not null check(baris_awal between 1 and 15),baris_akhir integer not null check(baris_akhir between 1 and 15),teks_utsmani text not null,unique(surah,ayat),check(baris_akhir>=baris_awal));
grant select,insert,update,delete on public.quran_ayat to authenticated; grant all on public.quran_ayat to service_role; alter table public.quran_ayat enable row level security;
create table public.santri(id uuid primary key default gen_random_uuid(),nis text not null unique,nama text not null,kelas text not null,halaqah_id uuid references public.halaqah(id),jalur text not null check(jalur in('iqro','tahfidz')),posisi_hafalan_ayat_id integer references public.quran_ayat(id),catatan text not null default '',aktif boolean not null default true);
grant select,insert,update,delete on public.santri to authenticated; grant all on public.santri to service_role; alter table public.santri enable row level security;
create table public.wali_santri(wali_id uuid references public.profiles(id),santri_id uuid references public.santri(id) on delete cascade,primary key(wali_id,santri_id));
grant select,insert,update,delete on public.wali_santri to authenticated; grant all on public.wali_santri to service_role; alter table public.wali_santri enable row level security;
create table public.setoran(id uuid primary key default gen_random_uuid(),santri_id uuid not null references public.santri(id),tanggal date not null,jenis text not null check(jenis in('sabaq','sabaqi','manzil')),tempat text not null check(tempat in('sekolah','rumah')),dari_ayat_id integer not null references public.quran_ayat(id),sampai_ayat_id integer not null references public.quran_ayat(id),jumlah_baris integer not null default 0,kali_ulang integer not null default 1 check(kali_ulang>0),nilai text check(nilai in('mumtaz','jayyid_jiddan','jayyid','maqbul','ulang')),catatan text not null default '',disimak boolean not null default false,diisi_oleh uuid not null references public.profiles(id) default auth.uid(),diparaf_oleh uuid references public.profiles(id),diparaf_pada timestamptz,created_at timestamptz not null default now(),check(sampai_ayat_id>=dari_ayat_id));
grant select,insert,update,delete on public.setoran to authenticated; grant all on public.setoran to service_role; alter table public.setoran enable row level security;
create table public.setoran_iqro(id uuid primary key default gen_random_uuid(),santri_id uuid not null references public.santri(id),tanggal date not null,tempat text not null check(tempat in('sekolah','rumah')),jilid integer not null check(jilid between 1 and 6),halaman_dari integer not null check(halaman_dari>0),halaman_sampai integer not null, kali_ulang integer not null default 1 check(kali_ulang>0),nilai text check(nilai in('lancar','kurang_lancar','ulang')),catatan text not null default '',disimak boolean not null default false,diisi_oleh uuid not null references public.profiles(id) default auth.uid(),diparaf_oleh uuid references public.profiles(id),diparaf_pada timestamptz,created_at timestamptz not null default now(),check(halaman_sampai>=halaman_dari));
grant select,insert,update,delete on public.setoran_iqro to authenticated; grant all on public.setoran_iqro to service_role; alter table public.setoran_iqro enable row level security;
create table public.kehadiran(id uuid primary key default gen_random_uuid(),santri_id uuid not null references public.santri(id),tanggal date not null,status text not null check(status in('hadir','sakit','izin','alpa')),dicatat_oleh uuid not null references public.profiles(id) default auth.uid(),unique(santri_id,tanggal));
grant select,insert,update,delete on public.kehadiran to authenticated; grant all on public.kehadiran to service_role; alter table public.kehadiran enable row level security;
create function public.consent_ready() returns boolean language sql stable security definer set search_path=public as $$select not public.has_role(auth.uid(),'wali') or exists(select 1 from public.profiles where id=auth.uid() and persetujuan_data_pada is not null)$$;
create function public.owns_child(_santri uuid) returns boolean language sql stable security definer set search_path=public as $$select public.has_role(auth.uid(),'wali') and public.consent_ready() and exists(select 1 from public.wali_santri where wali_id=auth.uid() and santri_id=_santri)$$;
create function public.teaches_halaqah(_halaqah uuid) returns boolean language sql stable security definer set search_path=public as $$select (public.has_role(auth.uid(),'ustadz') and exists(select 1 from public.halaqah where id=_halaqah and ustadz_id=auth.uid())) or (public.has_role(auth.uid(),'badal') and exists(select 1 from public.penugasan_badal where halaqah_id=_halaqah and ustadz_id=auth.uid() and (now() at time zone 'Asia/Jakarta')::date between mulai and selesai))$$;
create function public.can_read_halaqah(_halaqah uuid) returns boolean language sql stable security definer set search_path=public as $$select public.has_role(auth.uid(),'admin') or public.teaches_halaqah(_halaqah) or (public.has_role(auth.uid(),'pengawas') and exists(select 1 from public.halaqah where id=_halaqah and pengawas_id=auth.uid())) or (public.has_role(auth.uid(),'wali') and public.consent_ready() and exists(select 1 from public.santri s join public.wali_santri w on w.santri_id=s.id where s.halaqah_id=_halaqah and w.wali_id=auth.uid()))$$;
create function public.can_read_santri(_santri uuid) returns boolean language sql stable security definer set search_path=public as $$select public.has_role(auth.uid(),'admin') or public.owns_child(_santri) or exists(select 1 from public.santri s where s.id=_santri and (public.teaches_halaqah(s.halaqah_id) or (public.has_role(auth.uid(),'pengawas') and exists(select 1 from public.halaqah h where h.id=s.halaqah_id and h.pengawas_id=auth.uid()))))$$;
create function public.can_teach_santri(_santri uuid) returns boolean language sql stable security definer set search_path=public as $$select public.has_role(auth.uid(),'admin') or exists(select 1 from public.santri where id=_santri and public.teaches_halaqah(halaqah_id))$$;
revoke all on function public.consent_ready(),public.owns_child(uuid),public.teaches_halaqah(uuid),public.can_read_halaqah(uuid),public.can_read_santri(uuid),public.can_teach_santri(uuid) from public,anon;
grant execute on function public.consent_ready(),public.owns_child(uuid),public.teaches_halaqah(uuid),public.can_read_halaqah(uuid),public.can_read_santri(uuid),public.can_teach_santri(uuid) to authenticated;
create policy school_read on public.pengaturan_sekolah for select to authenticated using(true);
create policy period_read on public.periode for select to authenticated using(true);
create policy halaqah_read on public.halaqah for select to authenticated using(public.can_read_halaqah(id));
create policy badal_read on public.penugasan_badal for select to authenticated using(ustadz_id=auth.uid() or public.has_role(auth.uid(),'admin'));
create policy santri_read on public.santri for select to authenticated using(public.can_read_santri(id));
create policy santri_teacher_update on public.santri for update to authenticated using(public.can_teach_santri(id)) with check(public.has_role(auth.uid(),'admin') or public.teaches_halaqah(halaqah_id));
create policy relation_read on public.wali_santri for select to authenticated using(wali_id=auth.uid() or public.has_role(auth.uid(),'admin'));
create policy surah_read on public.quran_surah for select to authenticated using(true);
create policy ayat_read on public.quran_ayat for select to authenticated using(true);
create policy attendance_read on public.kehadiran for select to authenticated using(public.can_read_santri(santri_id));
create policy attendance_write on public.kehadiran for all to authenticated using(public.can_teach_santri(santri_id)) with check(public.can_teach_santri(santri_id) and dicatat_oleh=auth.uid());
do $$declare t text;begin foreach t in array array['pengaturan_sekolah','periode','halaqah','penugasan_badal','santri','wali_santri','quran_surah','quran_ayat'] loop execute format('create policy admin_manage on public.%I for all to authenticated using(public.has_role(auth.uid(),''admin'')) with check(public.has_role(auth.uid(),''admin''))',t);end loop;foreach t in array array['setoran','setoran_iqro'] loop execute format('create policy read_entries on public.%I for select to authenticated using(public.can_read_santri(santri_id))',t); execute format('create policy insert_entries on public.%I for insert to authenticated with check(diisi_oleh=auth.uid() and diparaf_oleh is null and diparaf_pada is null and (public.has_role(auth.uid(),''admin'') or (public.can_teach_santri(santri_id) and tempat=''sekolah'') or (public.owns_child(santri_id) and tempat=''rumah'')))',t); execute format('create policy update_entries on public.%I for update to authenticated using(public.has_role(auth.uid(),''admin'') or (public.can_teach_santri(santri_id) and tempat=''sekolah'') or (public.owns_child(santri_id) and tempat=''sekolah'')) with check(public.has_role(auth.uid(),''admin'') or (public.can_teach_santri(santri_id) and tempat=''sekolah'') or (public.owns_child(santri_id) and tempat=''sekolah''))',t); execute format('create policy admin_delete on public.%I for delete to authenticated using(public.has_role(auth.uid(),''admin''))',t);end loop;end$$;
create function public.validate_entry() returns trigger language plpgsql set search_path=public as $$declare first_verse public.quran_ayat; last_verse public.quran_ayat; child_jalur text;begin select jalur into child_jalur from public.santri where id=new.santri_id; if (tg_table_name='setoran' and child_jalur<>'tahfidz') or (tg_table_name='setoran_iqro' and child_jalur<>'iqro') then raise exception 'Jalur santri tidak sesuai';end if; if tg_op='UPDATE' and not public.has_role(auth.uid(),'admin') then if public.owns_child(old.santri_id) and not public.can_teach_santri(old.santri_id) then if (to_jsonb(new)-array['diparaf_oleh','diparaf_pada']) is distinct from (to_jsonb(old)-array['diparaf_oleh','diparaf_pada']) then raise exception 'Wali hanya dapat mengisi paraf';end if; if new.diparaf_oleh is distinct from auth.uid() or new.diparaf_pada is null then raise exception 'Paraf tidak sah';end if;new.diparaf_pada=now();else if new.santri_id<>old.santri_id or new.diisi_oleh<>old.diisi_oleh or new.tempat<>old.tempat or new.diparaf_oleh is distinct from old.diparaf_oleh or new.diparaf_pada is distinct from old.diparaf_pada then raise exception 'Kolom terlindungi';end if;end if;end if;if tg_table_name='setoran' then select * into first_verse from public.quran_ayat where id=new.dari_ayat_id;select * into last_verse from public.quran_ayat where id=new.sampai_ayat_id;if first_verse.id is null or last_verse.id is null then raise exception 'Referensi ayat tidak ditemukan';end if;new.jumlah_baris=(last_verse.halaman-first_verse.halaman)*15+last_verse.baris_akhir-first_verse.baris_awal+1;if new.jumlah_baris<1 then raise exception 'Rentang ayat tidak sah';end if;end if;return new;end$$;
create trigger validate_setoran before insert or update on public.setoran for each row execute function public.validate_entry();
create trigger validate_iqro before insert or update on public.setoran_iqro for each row execute function public.validate_entry();
create index santri_halaqah_idx on public.santri(halaqah_id);create index setoran_santri_date_idx on public.setoran(santri_id,tanggal);create index iqro_santri_date_idx on public.setoran_iqro(santri_id,tanggal);create index wali_child_idx on public.wali_santri(santri_id);